<?php require_once("../Model/DatabaseConnection.php"); $db=new DatabaseConnection(); $connection=$db->openConnection(); $users=$connection->query("SELECT * FROM users ORDER BY id DESC"); require("header.php"); ?>Users</div><?php require("footer.php"); ?><div class="tablebox"><h2>Users</h2><table class="table"><tr><th>ID</th><th>Name</th><th>Email</th><th>Phone</th><th>Role</th><th>Status</th><th>Actions</th></tr><?php while($u=$users->fetch_assoc()): ?><tr><td><?=$u['id']?></td><td><?=htmlspecialchars($u['name'])?></td><td><?=htmlspecialchars($u['email'])?></td><td><?=htmlspecialchars($u['phone'])?></td><td><form method="post" action="../Controller/userController.php?action=update" style="display:flex;gap:6px"><input type="hidden" name="id" value="<?=$u['id']?>"><select class="select" style="margin:0;width:auto" name="role"><option <?=$u['role']==='Admin'?'selected':''?>>Admin</option><option <?=$u['role']==='Seller'?'selected':''?>>Seller</option><option <?=$u['role']==='Delivery'?'selected':''?>>Delivery</option><option <?=$u['role']==='Customer'?'selected':''?>>Customer</option></select><select class="select" style="margin:0;width:auto" name="status"><option <?=$u['status']==='Active'?'selected':''?>>Active</option><option <?=$u['status']==='Inactive'?'selected':''?>>Inactive</option></select><button class="btn" type="submit">Save</button></form></td><td><?=$u['status']?></td><td><a class="btn danger" onclick="return confirm('Delete this user?')" href="../Controller/userController.php?action=delete&id=<?=$u['id']?>">Delete</a></td></tr><?php endwhile; ?></table></div></main></div></body></html>
